export default function ({
  name,
  kind,
  sheet,
  row,
  statusColumn,
  spreadsheetId,
  folderId,
  pricing,
}) {
  const types = [
    "Single Integration Native",
    "Single Integration Cred-only",
    "Single Integration Non-native",
    "Categories",
  ];
  if (
    !name ||
    !types.includes(kind) ||
    !sheet ||
    !Number.isInteger(row) ||
    row < 2 ||
    !/^[A-Z]+$/.test(statusColumn) ||
    !spreadsheetId ||
    !folderId ||
    !pricing
  )
    throw Error("Provide a valid job and destination");
  const safe = sheet.replace(/'/g, "''");
  return {
    job: {
      name,
      kind,
      sheet,
      row,
      statusColumn,
      spreadsheetId,
      folderId,
      pricing,
      range: `'${safe}'!${statusColumn}${row}`,
    },
    spreadsheetId,
    parents: [folderId],
    range: `'${safe}'!${statusColumn}${row}`,
  };
}

